package byx.demo;
import javafx.application.*;import javafx.scene.control.*;import javafx.stage.*;import java.nio.file.*;import java.awt.image.BufferedImage;import javax.imageio.ImageIO;
/** Test-only driver. Loaded from separate test classes against only the packaged application JAR. */
public final class DemoPackagedUiProbe extends Application {
 int checks;DemoApp app;Path evidence;
 void check(boolean v,String n){if(!v)throw new AssertionError(n);checks++;System.out.println("PASS "+n);}
 @Override public void start(Stage stage){try{evidence=Path.of(getParameters().getRaw().getFirst());Files.createDirectories(evidence);String origin=DemoApp.class.getProtectionDomain().getCodeSource().getLocation().toString();check(origin.contains("byx-mvp-demo-0.1.0.jar"),"PACKAGED_JAR_CLASS_ORIGIN");app=new DemoApp();app.start(stage);app.root.applyCss();app.root.layout();Platform.runLater(()->run(stage));}catch(Throwable t){t.printStackTrace();System.exit(1);}}
 void fireText(String text){app.root.applyCss();app.root.layout();var match=app.root.lookupAll("*").stream().filter(n->n instanceof ButtonBase b&&text.equals(b.getText())&&!b.isDisabled()).findFirst().orElseThrow(()->new AssertionError("Missing control: "+text));((ButtonBase)match).fire();app.root.applyCss();app.root.layout();}
 void screenshot(String name)throws Exception{app.root.applyCss();app.root.layout();var image=app.scene.snapshot(null);var reader=image.getPixelReader();var b=new BufferedImage((int)image.getWidth(),(int)image.getHeight(),BufferedImage.TYPE_INT_ARGB);for(int y=0;y<b.getHeight();y++)for(int x=0;x<b.getWidth();x++)b.setRGB(x,y,reader.getArgb(x,y));ImageIO.write(b,"png",evidence.resolve(name+".png").toFile());}
 void run(Stage s){try{check(app.root.lookup("#demo-login")!=null,"ORIGINAL_LOGIN_LAYOUT");screenshot("login");app.root.applyCss();app.root.layout();app.identifier.input().setText("teste-byx");app.password.input().setText("wrong");((Button)app.root.lookup("#demo-login")).fire();check(app.auth.session()==null&&app.shell==null,"WRONG_PASSWORD_REJECTED");app.root.applyCss();app.root.layout();app.identifier.input().setText("teste-byx");app.password.input().setText("byx123123");((Button)app.root.lookup("#demo-login")).fire();check(app.auth.session()!=null&&app.auth.session().role().equals("USER"),"USER_DEMO_LOGIN");check(app.router.route().equals("t-desk"),"TRADING_DESK");check(app.current instanceof panel.tradeview.TradingDesk,"APPROVED_DESK_COMPONENT");screenshot("desk");app.router.request("admin");check(app.router.route().equals("t-desk"),"ADMIN_ROUTE_DENIED");app.router.request("t-wallet");check(app.router.route().equals("t-desk"),"WALLET_ROUTE_DENIED");app.router.request("capture");check(app.router.route().equals("t-desk"),"RESEARCH_ROUTE_DENIED");app.router.request("t-markets");check(app.current instanceof panel.tradeview.MarketsPage,"MARKETS_PORTFOLIO");screenshot("markets");for(String route:java.util.List.of("t-home","t-positions","t-orders","t-history","h-faq","h-help","h-about")){app.router.request(route);check(app.router.route().equals(route),"NAV_"+route);}app.router.request("t-settings");check(app.current instanceof panel.accountview.SettingsScreen,"ORIGINAL_SETTINGS");panel.design.ByxTheme.select(panel.design.ThemeMode.LIGHT);check(panel.design.ByxTheme.mode()==panel.design.ThemeMode.LIGHT,"LIGHT_THEME");screenshot("light-settings");panel.design.ByxTheme.select(panel.design.ThemeMode.DARK);check(panel.design.ByxTheme.mode()==panel.design.ThemeMode.DARK,"DARK_THEME");fireText("Appearance");fireText("Compact");fireText("Save changes");check(!app.root.getStyleClass().contains("comfortable"),"DENSITY_COMPACT_SAVED");fireText("Comfortable");fireText("Save changes");check(app.root.getStyleClass().contains("comfortable"),"DENSITY_COMFORTABLE_SAVED");for(var mode:java.util.List.of(panel.motion.MotionPreference.REDUCED,panel.motion.MotionPreference.OFF,panel.motion.MotionPreference.FULL)){fireText(mode.name());fireText("Save changes");check(app.motion.preference.get()==mode,"MOTION_SETTINGS_SAVED_"+mode);}app.router.request("t-desk");((ComboBox<String>)app.root.lookup("#demo-watchlist")).setValue("BTCUSDT");check(app.symbol.equals("BTCUSDT"),"WATCHLIST_LOCAL");app.palette.open();check(app.palette.isOpen(),"COMMAND_PALETTE");app.palette.close();((Button)app.root.lookup("#demo-logout")).fire();app.root.applyCss();app.root.layout();check(app.auth.session()==null&&app.root.lookup("#demo-login")!=null,"LOGOUT_RETURNS_LOGIN");app.router.request("t-desk");check(app.auth.session()==null,"SESSION_ENDED_GATE");app.cleanup();s.close();Files.writeString(evidence.resolve("packaged-ui-result.txt"),"PASS="+checks+" FAIL=0 ERROR=0 SKIP=0\nOrigin="+DemoApp.class.getProtectionDomain().getCodeSource().getLocation());Platform.exit();}catch(Throwable t){t.printStackTrace();try{app.cleanup();}catch(Throwable ignored){}System.exit(1);}}
 public static void main(String[] args){launch(args);}
}